code = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
print('Sheet names:', wb.sheetnames)
print('Validation sample formulas:')
for addr in ['H12','H19','H26','H35','H40','H50']:
    print(addr, repr(ws[addr].value), 'data_type=', ws[addr].data_type)
print('H42:H47:')
for r in range(42,48):
    print(f'H{r}', 'label=', repr(ws.cell(r,5).value), 'formula=', repr(ws.cell(r,8).value), 'data_type=', ws.cell(r,8).data_type)
# Comprehensive validation
ranges = ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
errors=[]
for range_addr in ranges:
    for row in ws[range_addr]:
        for cell in row:
            v=cell.value
            if not isinstance(v,str) or not v.startswith('='):
                errors.append(f'{cell.coordinate} is not a formula string: {v!r}')
            if isinstance(v,str) and ('PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v):
                errors.append(f'{cell.coordinate} uses disallowed percentile variant: {v}')
# Expected label mapping check
expected = {
    42: '=MIN(H$35:H$40)',
    43: '=MAX(H$35:H$40)',
    44: '=MEDIAN(H$35:H$40)',
    45: '=AVERAGE(H$35:H$40)',
    46: '=PERCENTILE(H$35:H$40,0.25)',
    47: '=PERCENTILE(H$35:H$40,0.75)',
}
for r, exp in expected.items():
    if ws.cell(r,8).value != exp:
        errors.append(f'H{r} expected {exp}, got {ws.cell(r,8).value}')
# Verify no added sheets and formatting preserved in representative yellow cells
if wb.sheetnames != ['Task','Data']:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')
if errors:
    print('VALIDATION_ERRORS')
    for e in errors:
        print(e)
    raise SystemExit(1)
print('Validation OK: all target cells contain formula strings; PERCENTILE used; no added sheets.')
'''
res=terminal('python3 - <<\'PY\'\n'+code+'\nPY', timeout=120)
print(res['output'])
if res['exit_code'] != 0:
    raise SystemExit(res['exit_code'])"}
